(window.CRAM_PERSONAL=window.CRAM_PERSONAL||{})["physical-diagnosis-2-exam-2"]={"title":"Physical Diagnosis 2 Exam 2","sections":[{"id":"l5-emphasis","title":"★ What the lecture kept coming back to","style":"--acc:#b8860b;--acc-bg:#f5eedd;--acc-zebra:#faf7ee;--acc-ink:#906909"},{"id":"l5-history","title":"The Cardiac History","style":"--acc:#3a5a40;--acc-bg:#e3e8e4;--acc-zebra:#f1f3f2;--acc-ink:#2d4632"},{"id":"l5-cycle","title":"Cardiac Cycle & Heart Sounds","style":"--acc:#46704f;--acc-bg:#e5ebe6;--acc-zebra:#f2f5f3;--acc-ink:#37573e"},{"id":"l5-impulse","title":"Apical Impulse & Point of Maximal Impulse","style":"--acc:#5f8a68;--acc-bg:#e9efea;--acc-zebra:#f4f7f4;--acc-ink:#4a6c51"},{"id":"l5-auscultation","title":"Auscultation — Areas, Diaphragm & Bell","style":"--acc:#2f6b5e;--acc-bg:#e2eae8;--acc-zebra:#f0f5f4;--acc-ink:#255349"},{"id":"l5-murmur-describe","title":"Describing & Grading Murmurs","style":"--acc:#c08a2e;--acc-bg:#f6efe2;--acc-zebra:#fbf7f0;--acc-ink:#966c24"},{"id":"l5-murmurs","title":"The Murmurs One by One","style":"--acc:#7a3b3b;--acc-bg:#ece4e4;--acc-zebra:#f6f1f1;--acc-ink:#5f2e2e"},{"id":"l5-maneuvers","title":"Maneuvers","style":"--acc:#5b4a8a;--acc-bg:#e8e6ef;--acc-zebra:#f4f2f7;--acc-ink:#473a6c"},{"id":"l5-peripheral","title":"Peripheral Vascular Examination","style":"--acc:#8a5a2b;--acc-bg:#efe8e1;--acc-zebra:#f7f3f0;--acc-ink:#6c4622"},{"id":"l5-edema","title":"Peripheral Edema","style":"--acc:#3f5b6b;--acc-bg:#e4e8ea;--acc-zebra:#f2f4f5;--acc-ink:#314753"},{"id":"l5-exam","title":"Running the Examination","style":"--acc:#4a4a4a;--acc-bg:#e6e6e6;--acc-zebra:#f2f2f2;--acc-ink:#3a3a3a"}],"rows":[{"t":"★ The sound is not the diagnosis","d":"Document what you hear, when and where: 'grade 4/6 systolic ejection murmur, crescendo-decrescendo, loudest at the right 2nd intercostal space, radiating to the carotids, with a thrill.' The disease name (aortic stenosis) goes in the differential, not the physical examination.","s":0},{"t":"★ Try before you buy","d":"Tricuspid is the FIRST valve blood crosses on its way back to the heart (tricuspid before bicuspid/mitral). Said twice: 'That is important, that is important.'","s":0},{"t":"★ Hypertrophic obstructive cardiomyopathy","d":"Learn this murmur so you do not sign off a sports physical wrongly. Aortic and pulmonic stenosis worry you at a point; this one worries you, period. Murmur LOUDER with Valsalva or standing = echocardiogram, no activity until done.","s":0},{"t":"★ Mitral vs tricuspid regurgitation","d":"Both pansystolic. Mitral (apex) radiates to the LEFT AXILLA; tricuspid (lower left sternal border) does NOT. Loudest spot plus the axilla decides it.","s":0},{"t":"★ The thrill is the jump","d":"Loudness raises the grade, but a palpable thrill makes it at least grade 4/6. An arteriovenous fistula is what a thrill feels like.","s":0},{"t":"★ Weight before swelling","d":"Up to 10% of body weight can accumulate before pitting shows. Two pounds overnight is water. Daily morning weight; know a dialysis or heart failure patient's dry weight.","s":0},{"t":"★ Syncope: before and after","d":"Prodrome (lightheaded, pale, clammy) = vasovagal. On standing = orthostatic. Sudden, no warning = arrhythmia. Confused afterward = postictal, think seizure. Feel faint? Sit down.","s":0},{"t":"★ Negative Homans does not reassure","d":"Do it when you already suspect deep vein thrombosis, on the worrying leg. Positive confirms suspicion; negative in a high-risk story, still worried.","s":0},{"t":"Time on topic","d":"No exam-scope statements in 138 minutes. Cardiac content took about 110 minutes; peripheral vascular about 25 ('almost entirely review... the cardiac stuff is a lot of new').","s":0},{"t":"Symptoms to ask","d":"Chest pain, palpitations, dyspnea, orthopnea, paroxysmal nocturnal dyspnea, edema, syncope. Quantify the baseline level of activity.","s":1},{"t":"Chest pain","d":"Most common symptom of coronary artery disease. Always consider angina, myocardial infarction, dissecting aortic aneurysm, pulmonary embolism. Open-ended first, then details; ask the patient to point.","s":1},{"t":"Atypical presentation","d":"Women over 65: upper back, neck or jaw pain, shortness of breath, paroxysmal nocturnal dyspnea, nausea, vomiting, fatigue.","s":1},{"t":"Palpitations","d":"Unpleasant awareness of the heartbeat (skipping, racing, fluttering, pounding). Anxiety and hyperthyroidism cause them; not necessarily heart disease. Get an electrocardiogram.","s":1},{"t":"Dyspnea","d":"Uncomfortable awareness of breathing inappropriate to the level of exertion. Cardiac or pulmonary.","s":1},{"t":"Orthopnea","d":"Dyspnea supine, better sitting up. Count the pillows, and ask what they are for.","s":1},{"t":"Paroxysmal nocturnal dyspnea","d":"Sudden dyspnea waking the patient, usually 1-2 hours after going to bed; sits up or goes to the window. May wheeze and cough.","s":1},{"t":"Syncope","d":"Transient loss of consciousness with recovery. Most common: neurocardiogenic (vasovagal). Arrhythmia in about 20%.","s":1},{"t":"Systole vs diastole","d":"Named for the VENTRICLES. Systole: contraction, S1 to S2. Diastole: relaxation and filling, S2 to S1.","s":2},{"t":"S1 (lub)","d":"Mitral + tricuspid closure. Diaphragm, apex. Usually not split. Precedes the carotid pulse.","s":2},{"t":"S2 (dub)","d":"Aortic (A2, usually louder) + pulmonic (P2) closure. Diaphragm, base. Follows the carotid pulse.","s":2},{"t":"Physiologic splitting","d":"S2 split on INSPIRATION, fused on expiration. Normal. Best at the pulmonic area.","s":2},{"t":"Pathologic splitting","d":"Audible split on EXPIRATION: suggests heart disease. Tends to be fixed.","s":2},{"t":"Early ejection sound","d":"Just after S1; high, clicking; diaphragm. Aortic: base and apex, no change with inspiration. Pulmonic: 2nd-3rd intercostal spaces, decreases with inspiration.","s":2},{"t":"Click","d":"Mid to late systolic, at or medial to the apex; high, diaphragm. Mitral valve prolapse; followed by a late systolic murmur crescendoing to S2.","s":2},{"t":"S3 ventricular gallop","d":"After S2: Ken-TUC-ky. Bell, apex, left lateral decubitus. Normal to about 35-40 and in late pregnancy; over 40 = heart failure, volume overload.","s":2},{"t":"S4 atrial gallop","d":"Before S1: Ten-nes-SEE. Dull, low; bell, apex, left lateral decubitus. Stiff ventricle: hypertension, aortic stenosis. Normal in athletes and older adults. Right-sided S4 at lower left sternal border, louder with inspiration.","s":2},{"t":"Opening snap","d":"Very early diastole, stenotic MITRAL valve. HIGH pitch, diaphragm. Can be mistaken for P2. Fades as the leaflets calcify.","s":2},{"t":"Normal","d":"5th intercostal space at or just medial to the left midclavicular line. Marks the LEFT border of the heart. About 2.5 cm (a quarter), brisk and tapping.","s":3},{"t":"Displaced","d":"Enlarged heart: lateral and possibly inferior (for example 6th space, anterior axillary line). Document where you find it.","s":3},{"t":"Can't find it","d":"Left lateral decubitus; then exhale fully and hold.","s":3},{"t":"Hyperkinetic","d":"Increased stroke volume; not necessarily disease. Anxiety, hyperthyroidism, severe anemia. Normal location, under 2/3 of systole.","s":3},{"t":"Sustained (pressure load)","d":"Hypertrophy, increased afterload. Left: aortic stenosis, hypertension. Right: pulmonic stenosis, pulmonary hypertension.","s":3},{"t":"Diffuse (volume load)","d":"Dilation, increased preload. Left: displaced left and down; aortic or mitral regurgitation, cardiomyopathy. Right: atrial septal defect.","s":3},{"t":"Why the areas are where they are","d":"Not over the valves: the next place DOWNSTREAM along the blood flow with no bone in the way. Aortic stenosis can radiate to both carotids.","s":4},{"t":"The five areas","d":"Aortic (right 2nd space), pulmonic (left 2nd), Erb's point (between pulmonic and mitral), tricuspid (lower left sternal border), mitral (apex).","s":4},{"t":"Bell","d":"Low pitch. Light pressure, no gaps. Apex, then medially along the lower sternal border. S3, S4, mitral stenosis.","s":4},{"t":"Diaphragm","d":"High pitch. Press firmly, whole precordium. S1, S2, clicks, opening snap, aortic and mitral regurgitation, friction rubs.","s":4},{"t":"Technique","d":"Quiet room, skin contact always (never over clothing), isolate each sound, close your eyes. Unsure if systolic? Palpate the carotid while listening.","s":4},{"t":"Murmur / thrill / bruit","d":"Murmur: turbulent flow over a valve, heard. Thrill: its vibration, felt with the balls of the hand held still. Bruit: turbulent flow in a vessel.","s":5},{"t":"Causes of a murmur","d":"Partially obstructed valve; increased flow through a normal valve (child); ejection into a dilated chamber; regurgitation; shunting to a lower pressure chamber.","s":5},{"t":"Seven characteristics","d":"Timing, shape, location, radiation, intensity, pitch, quality.","s":5},{"t":"Shapes","d":"Crescendo-decrescendo (diamond); decrescendo (starts maximal, fades); plateau (unchanging); crescendo (grows).","s":5},{"t":"Levine grades","d":"1 heard only after tuning in. 2 heard immediately. 3 moderately loud. 4 loud WITH THRILL. 5 thrill, heard with stethoscope partly off. 6 thrill, heard entirely off.","s":5},{"t":"Pitch and quality","d":"High, medium, low. Blowing, harsh, rumbling, musical.","s":5},{"t":"Innocent","d":"No structural abnormality; grade 1-3; softer on standing, sitting up or Valsalva; childhood. Defined by no symptoms or structural disease, not by grade. A thrill = not innocent.","s":5},{"t":"Physiologic vs pathologic","d":"Physiologic: anemia, pregnancy, fever, hyperthyroidism. Pathologic: structural (aortic or pulmonic stenosis, hypertrophic cardiomyopathy, atrial septal defect).","s":5},{"t":"Aortic stenosis","d":"Midsystolic, crescendo-decrescendo</td><td>Medium, harsh</td><td>Aortic area</td><td>Carotids, down left sternal border, even apex</td><td>Sitting forward; louder with squatting and leg raise","s":6},{"t":"Pulmonic stenosis","d":"Midsystolic, crescendo-decrescendo</td><td>Medium, harsh</td><td>Pulmonic area</td><td>Left shoulder and neck if loud</td><td>None","s":6},{"t":"Hypertrophic cardiomyopathy","d":"Midsystolic, crescendo-decrescendo</td><td>Medium, harsh</td><td>Erb's point, tricuspid area</td><td>Down left sternal border to apex; NEVER the neck</td><td>Softer with squatting; LOUDER with Valsalva and standing","s":6},{"t":"Tricuspid regurgitation","d":"Pansystolic, plateau</td><td>Medium, blowing</td><td>Lower left sternal border</td><td>Right sternum, xiphoid; NOT the axilla</td><td>May increase slightly with inspiration","s":6},{"t":"Mitral regurgitation","d":"Pansystolic, holosystolic</td><td>Medium-high, harsh</td><td>Apex</td><td>LEFT AXILLA</td><td>Louder with handgrip or squatting; apical thrill if loud","s":6},{"t":"Aortic regurgitation","d":"Early diastolic, decrescendo; grade 1-3</td><td>High, blowing (like breath sounds)</td><td>Aortic area, down left spaces</td><td>Apex if loud</td><td>Sit forward, exhale, hold","s":6},{"t":"Pulmonic regurgitation","d":"Early diastolic, decrescendo; grade 1-3</td><td>High</td><td>Pulmonic area</td><td>None</td><td>None; may increase with inspiration","s":6},{"t":"Mitral stenosis","d":"Mid to late diastolic, decrescendo; grade 1-4</td><td>Low rumble: BELL</td><td>Apex</td><td>Little or none</td><td>Bell at the apical impulse, left lateral decubitus","s":6},{"t":"Tricuspid stenosis","d":"Mid to late diastolic, decrescendo; grade 1-4</td><td>Low rumble after an opening snap: bell</td><td>Lower left sternal border near xiphoid</td><td>Little or none</td><td>Bell","s":6},{"t":"Pericardial friction rub","d":"Scratchy, both systole and diastole; plateau</td><td>High: diaphragm</td><td>Erb's point</td><td>Little</td><td>Louder leaning forward, exhaled, breath held","s":6},{"t":"Valsalva (strain)","d":"Forceful expiration against a closed airway: bear down, or push against your hand on the mid-abdomen. Less preload. Hypertrophic cardiomyopathy LOUDER; aortic stenosis softer or unchanged.","s":7},{"t":"Standing from squatting","d":"Less venous return, less preload. Hypertrophic cardiomyopathy LOUDER; aortic stenosis SOFTER; mitral prolapse click earlier, murmur longer.","s":7},{"t":"Squatting from standing or leg raise","d":"More venous return, more preload. Hypertrophic cardiomyopathy SOFTER; aortic stenosis LOUDER; mitral prolapse click later, murmur shorter.","s":7},{"t":"Isometric handgrip","d":"Raises resistance. Increases mitral regurgitation, pulmonic stenosis, ventricular septal defect, aortic regurgitation, mitral stenosis.","s":7},{"t":"The one rule","d":"Smaller left ventricle = more outflow obstruction in hypertrophic cardiomyopathy. More blood through a fixed narrow valve = louder aortic stenosis.","s":7},{"t":"Positions","d":"Left lateral decubitus: apex (S3, S4, mitral stenosis). Seated, leaning forward, exhaled: aortic regurgitation, friction rub.","s":7},{"t":"Inspection","d":"Size, symmetry, venous pattern, hair growth, edema, skin color, ulcers. Always compare sides.","s":8},{"t":"Capillary refill","d":"2-3 seconds. Quincke's sign: nail bed flashes red to pale with each beat.","s":8},{"t":"Pulse grades","d":"4+ bounding, 3+ increased, 2+ brisk normal, 1+ faint, 0 absent. ALWAYS compare both sides.","s":8},{"t":"Arterial insufficiency","d":"Claudication to rest pain; pale or dusky red; cool; NO edema; thin shiny hairless skin; painful toe ulcer; gangrene; decreased pulses; pallor on elevation, dependent rubor.","s":8},{"t":"Venous insufficiency","d":"No pain; brown hemosiderin staining; normal temperature; pitting edema; thickened skin; ulcer at the medial and lateral malleolus; gangrene rare; NORMAL pulses.","s":8},{"t":"Pulse landmarks","d":"Brachial: medial to biceps tendon. Radial: lateral wrist. Ulnar: medial wrist, may be impalpable. Femoral: below inguinal ligament, midway anterior superior iliac spine to pubic symphysis. Dorsalis pedis: lateral to great toe extensor tendon. Posterior tibial: behind medial malleolus.","s":8},{"t":"Carotid","d":"Hold breath, auscultate BEFORE palpating, one side at a time.","s":8},{"t":"Pulse lag","d":"Radial and femoral together; femoral lag = coarctation of the aorta.","s":8},{"t":"Bruit sites","d":"Aorta (upper midline); renal 3-4 cm lateral to aorta; iliac 3-4 cm lateral to umbilicus, about 2 cm below; femoral.","s":8},{"t":"Allen test","d":"Compress radial and ulnar, clench 30 s, open; release ULNAR and watch the hand pink up; repeat for radial. Persistent pallor = occlusion. Done before an arterial blood gas.","s":8},{"t":"Ankle brachial index","d":"Higher ankle pressure (dorsalis pedis or posterior tibial) over brachial systolic, each leg, 2 decimals. Supine 10 min; inflate 20 mm Hg above last pulse; deflate 1 mm Hg per second.","s":8},{"t":"Index values","d":"Over 1.40 noncompressible calcified vessel. 0.90-1.40 normal. Under 0.90 peripheral arterial disease. Under 0.50 severe.","s":8},{"t":"Homans sign","d":"Knee bent, dorsiflex the foot quickly and forcefully; pain BEHIND THE KNEE = positive. Deep vein thrombosis.","s":8},{"t":"Definition","d":"Excess fluid in the extravascular interstitial space. Up to 10% of body weight before pitting. Obscures veins, tendons, bony prominences.","s":9},{"t":"Technique","d":"Thumb pressed firmly at least 2 seconds over the dorsum of the foot, behind the medial malleolus, or the shins. Describe depth AND extent. Unilateral or bilateral?","s":9},{"t":"1+","d":"2 mm, disappears rapidly.","s":9},{"t":"2+","d":"4 mm, gone in 10-15 seconds.","s":9},{"t":"3+","d":"6 mm, may last more than 1 minute.","s":9},{"t":"4+","d":"8 mm, can last more than 2 minutes.","s":9},{"t":"Order","d":"Inspection (including jugular venous pressure), palpation, auscultation, special techniques.","s":10},{"t":"Equipment and room","d":"Stethoscope, ruler, penlight, tongue depressor. Tangential light, quiet room, warm hands, short nails.","s":10},{"t":"The patient","d":"In a gown; never examine over clothing. Positioning: 30-45 degrees, left lateral decubitus, seated leaning forward.","s":10},{"t":"Cardiac OSCE (objective structured clinical examination)","d":"21 October. The whole station is on the Cardiac OSCE run-sheet.","s":10}],"map":{"physical-diagnosis-2-exam-2-cardiovascular-exam-quiz-version-2":[74,23,82,-1,47,12,72,-1,39,10,58,66,68,-1,22,69,35,24,56,67,-1,15,55,63,17,55,32,48,-1,-1],"physical-diagnosis-2-exam-2-cardiovascular-exam-quiz":[30,54,70,36,-1,13,-1,26,71,44,31,-1,10,-1,66,-1,68,76,45,37,72,71,26,57,53,24,65,51,39,45]}};
